//! The grammars this repo builds: `grammars.toml` (generated by
//! `scripts/sync-pins.py`) and `exclusions.toml` (kept by hand), compiled into
//! the binary so a build of version `v` always uses `v`'s pins.

use std::collections::BTreeSet;
use std::fmt;

use serde::Deserialize;

const GRAMMARS: &str = include_str!("../grammars.toml");
const EXCLUSIONS: &str = include_str!("../exclusions.toml");

/// The longest language name whose archive, `<name>.tar.gz`, still fits the
/// 100 bytes a ustar header gives a member's name.
const MAX_NAME_LEN: usize = 100 - ".tar.gz".len();

/// One language's grammar: where its source is, and the C function that
/// returns it.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Pin {
    pub(crate) name: String,
    pub(crate) url: String,
    /// A full commit SHA.
    pub(crate) rev: String,
    /// The directory holding the grammar's `src/` within its repository,
    /// empty for the root.
    pub(crate) subpath: String,
    pub(crate) symbol: String,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct GrammarsFile {
    #[serde(rename = "helix-rev")]
    helix_rev: String,
    #[serde(default)]
    language: Vec<Pin>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ExclusionsFile {
    #[serde(default)]
    exclude: Vec<Exclusion>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Exclusion {
    name: String,
    /// Empty for every platform.
    #[serde(default)]
    platforms: Vec<String>,
    reason: String,
}

/// Every pinned language, sorted by name, and the Helix commit whose queries
/// they ship with.
pub(crate) struct Pins {
    helix_rev: String,
    languages: Vec<Pin>,
    exclusions: Vec<Exclusion>,
}

/// Why the pins are unusable.
#[derive(Debug)]
pub(crate) struct PinsError(String);

impl fmt::Display for PinsError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl Pins {
    pub(crate) fn embedded() -> Result<Self, PinsError> {
        Self::parse(GRAMMARS, EXCLUSIONS)
    }

    pub(crate) fn parse(grammars: &str, exclusions: &str) -> Result<Self, PinsError> {
        let GrammarsFile {
            helix_rev,
            mut language,
        } = toml::from_str(grammars).map_err(|e| PinsError(format!("grammars.toml: {e}")))?;
        let ExclusionsFile { exclude } =
            toml::from_str(exclusions).map_err(|e| PinsError(format!("exclusions.toml: {e}")))?;
        check_rev("helix-rev", &helix_rev)?;
        language.sort_by(|a, b| a.name.cmp(&b.name));
        for pair in language.windows(2) {
            if pair[0].name == pair[1].name {
                return Err(PinsError(format!(
                    "language {:?} is pinned twice",
                    pair[0].name
                )));
            }
        }
        for pin in &language {
            check_pin(pin)?;
        }
        let pinned: BTreeSet<&str> = language.iter().map(|pin| pin.name.as_str()).collect();
        for exclusion in &exclude {
            if !pinned.contains(exclusion.name.as_str()) {
                return Err(PinsError(format!(
                    "exclusion of {:?}, which is not pinned",
                    exclusion.name
                )));
            }
            if exclusion.reason.trim().is_empty() {
                return Err(PinsError(format!(
                    "exclusion of {:?} gives no reason",
                    exclusion.name
                )));
            }
        }
        Ok(Self {
            helix_rev,
            languages: language,
            exclusions: exclude,
        })
    }

    pub(crate) fn helix_rev(&self) -> &str {
        &self.helix_rev
    }

    pub(crate) fn get(&self, name: &str) -> Option<&Pin> {
        self.languages
            .binary_search_by(|pin| pin.name.as_str().cmp(name))
            .ok()
            .map(|i| &self.languages[i])
    }

    /// The languages a release for `platform` holds: every pin its
    /// exclusions leave in.
    pub(crate) fn release(&self, platform: &str) -> Vec<&Pin> {
        self.languages
            .iter()
            .filter(|pin| {
                !self.exclusions.iter().any(|exclusion| {
                    exclusion.name == pin.name
                        && (exclusion.platforms.is_empty()
                            || exclusion.platforms.iter().any(|p| p == platform))
                })
            })
            .collect()
    }
}

fn check_pin(pin: &Pin) -> Result<(), PinsError> {
    if !is_language_name(&pin.name) {
        return Err(PinsError(format!(
            "language name {:?} must be lowercase ASCII letters, digits, '.', '_' or '-', \
             not start with '.', and be at most {MAX_NAME_LEN} bytes",
            pin.name
        )));
    }
    check_rev(&pin.name, &pin.rev)?;
    if !is_c_identifier(&pin.symbol) {
        return Err(PinsError(format!(
            "{}: symbol {:?} is not a C identifier",
            pin.name, pin.symbol
        )));
    }
    Ok(())
}

fn check_rev(what: &str, rev: &str) -> Result<(), PinsError> {
    if rev.len() == 40 && rev.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f')) {
        Ok(())
    } else {
        Err(PinsError(format!(
            "{what}: rev {rev:?} is not a full commit SHA"
        )))
    }
}

/// Lowercase so names stay distinct on case-insensitive file systems, and
/// no leading dot so an archive is never a dotfile.
fn is_language_name(name: &str) -> bool {
    let allowed = |b: u8| matches!(b, b'a'..=b'z' | b'0'..=b'9' | b'.' | b'_' | b'-');
    name.len() <= MAX_NAME_LEN
        && name.bytes().all(allowed)
        && name.bytes().next().is_some_and(|b| b != b'.')
}

fn is_c_identifier(symbol: &str) -> bool {
    symbol
        .bytes()
        .next()
        .is_some_and(|b| b.is_ascii_alphabetic() || b == b'_')
        && symbol
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_')
}

